#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="1.0.0-rc7"
EXPECTED_SHA256="4ab7a6ac41cbb3aa3a563d594850f6ea709f6b893fae5b4a52baadfe0cab20c4"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 1.0.0-rc7 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_1.0.0-rc7.sh --verify
  bash HADS_Next_install_1.0.0-rc7.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_1.0.0-rc7.sh --install-dev
  bash HADS_Next_install_1.0.0-rc7.sh --upgrade-rc6
Nová instalace přidá local_hads_next_practical. Výslovný --upgrade-rc6 aktualizuje jen ověřený Next RC6 přes nativní Supervisor update; zachová /data a vyžádá nativní částečnou zálohu. Starý Hermes 2.0.0-rc3 se nemění.
Původní Hermes je součástí balíčku. AI i vlastní testovací opravný katalog vyžadují výslovný souhlas. Obecné produkční zápisy jsou zakázané. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev|--upgrade-rc6) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
base64 -d > "$STAGING/payload.tar.gz" <<'HADS_NEXT_PAYLOAD'
